                     "source_step_sha256s": center_task["source_step_sha256s"],
                     "source_match_lineage": center_lineage["source_match_lineage"],
                     "lineage": center_lineage,
                     "meta_sha256": center_proof["meta_sha256"], "execution_mode": "mock_only"}
